// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.sail.lmdb.TxnManager.Txn;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * The predicate-object guarantee cache is what the planner reads when it drops or narrows a filter through a finite
 * anchor. Incremental updates only ever weaken a guarantee, so the weakened guarantee must be visible to readers no
 * later than the rows that weakened it: a query that opens its snapshot right after {@code mdb_txn_commit} must never
 * plan against the previous, stronger guarantee (review 3.5).
 */
class TripleStoreGuaranteePublicationTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final long PREDICATE = 2L;

	private ValueStore valueStore;
	private TripleStore tripleStore;

	@BeforeEach
	void before(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		valueStore = new ValueStore(new File(dataDir, "values"), config);
		tripleStore = new TripleStore(new File(dataDir, "triples"), config, valueStore);
	}

	@AfterEach
	void after() throws Exception {
		try {
			tripleStore.close();
		} finally {
			valueStore.close();
		}
	}

	@Test
	void weakenedGuaranteeIsPublishedNoLaterThanTheCommittedRows() throws Exception {
		tripleStore.startTransaction();
		tripleStore.storeTriple(1, PREDICATE, 3, 0, true);
		tripleStore.recordRdfTermDomain(PREDICATE, VF.createLiteral("7", XSD.INT));
		tripleStore.commit();
		RdfTermDomain strong = tripleStore.getCachedRdfTermDomain(PREDICATE).orElseThrow();
		assertTrue(strong.has(RdfTermDomain.Fact.CANONICAL_INTEGER), () -> "initial guarantee: " + strong);

		// Observe the heap guarantee at the instant the committed rows become visible to new read transactions
		// (the barrier runs right after mdb_txn_commit; a read transaction cannot be opened from inside it because
		// the committing writer still holds the transaction manager's lock).
		List<Optional<RdfTermDomain>> observedAtCommit = new ArrayList<>();
		tripleStore.durableCommitBarrierForTesting = () -> observedAtCommit
				.add(tripleStore.getCachedRdfTermDomain(PREDICATE));

		tripleStore.startTransaction();
		tripleStore.storeTriple(1, PREDICATE, 4, 0, true);
		tripleStore.recordRdfTermDomain(PREDICATE, VF.createLiteral("007", XSD.INT));
		tripleStore.commit();
		tripleStore.durableCommitBarrierForTesting = null;

		try (Txn txn = tripleStore.getTxnManager().createReadTxn()) {
			assertEquals(2, count(tripleStore.getTriples(txn, -1, PREDICATE, -1, -1, true)),
					"both rows are visible once the commit completed");
		}
		assertEquals(1, observedAtCommit.size(), "exactly one durable commit expected");
		RdfTermDomain atCommit = observedAtCommit.getFirst()
				.orElseThrow(() -> new AssertionError("guarantee missing at commit"));
		assertTrue(atCommit.has(RdfTermDomain.Fact.NUMBER), () -> "guarantee at commit: " + atCommit);
		assertFalse(atCommit.has(RdfTermDomain.Fact.CANONICAL_INTEGER),
				() -> "a reader opening its snapshot at commit must already see the weakened guarantee, not "
						+ atCommit);

		RdfTermDomain afterCommit = tripleStore.getCachedRdfTermDomain(PREDICATE).orElseThrow();
		assertEquals(atCommit, afterCommit, "the post-commit publication must be idempotent");
		assertEquals(tripleStore.getPersistedRdfTermDomain(PREDICATE), Optional.of(afterCommit),
				"heap and disk guarantees agree once the commit completed");
	}

	@Test
	void unchangedGuaranteeStaysPublishedAcrossCommitsWithoutGuaranteeWrites() throws Exception {
		tripleStore.startTransaction();
		tripleStore.storeTriple(1, PREDICATE, 3, 0, true);
		tripleStore.recordRdfTermDomain(PREDICATE, VF.createLiteral("7", XSD.INT));
		tripleStore.commit();
		RdfTermDomain before = tripleStore.getCachedRdfTermDomain(PREDICATE).orElseThrow();

		List<Optional<RdfTermDomain>> observedAtCommit = new ArrayList<>();
		tripleStore.durableCommitBarrierForTesting = () -> observedAtCommit
				.add(tripleStore.getCachedRdfTermDomain(PREDICATE));
		tripleStore.startTransaction();
		tripleStore.storeTriple(5, PREDICATE, 3, 0, true);
		tripleStore.recordRdfTermDomain(PREDICATE, VF.createLiteral("7", XSD.INT));
		tripleStore.commit();
		tripleStore.durableCommitBarrierForTesting = null;

		assertEquals(List.of(Optional.of(before)), observedAtCommit);
		assertEquals(before, tripleStore.getCachedRdfTermDomain(PREDICATE).orElseThrow());
	}

	private static int count(RecordIterator iterator) throws Exception {
		try (iterator) {
			int count = 0;
			while (iterator.next() != null) {
				count++;
			}
			return count;
		}
	}
}
